int n, m;
int h[N];
char c;

void solve() {
	cin >> n >> m;
	for (int i = 0; i < n; i++) {
		for (int j = 0; j < m; j++) {
			cin >> c;
			if (c == '*') {
				h[j] = max(h[j], n - i);
			}
		}
	}
	int maxU = 0, maxD = 0;
	for (int i = 0; i < m - 1; i++) {
		int diff = h[i + 1] - h[i];
		if (diff > 0) {
			maxU = max(maxU, diff);
		} else {
			maxD = max(maxD, -diff);
		}
	}
	cout << maxU << ' ' << maxD << endl;
}

