const int N = 200200;

int n, m;
int x[N];
int u[N], t[N];

bool read() {
	if (!(cin >> n >> m)) return false;
	forn(i, n) assert(scanf("%d", &x[i]) == 1);
	forn(i, m) assert(scanf("%d%d", &u[i], &t[i]) == 2);
	return true;
}

pti segs[N];

void solve() {
	forn(i, m) segs[i] = mp(u[i] - t[i], u[i] + t[i]);

	sort(x, x + n);
	sort(segs, segs + m);

	int ans = 0;
	multiset<int> z;
	for (int i = 0, j = 0; i < n; ) {
		if (j < m && segs[j].x <= x[i]) {
			z.insert(segs[j].y);
			j++;
		} else {
			auto it = z.lower_bound(x[i]);
			i++;
			if (it != z.end()) {
				ans++;
				z.erase(it);
			}
		}
	}
	cout << ans << endl;
}

for (int i = 0; i < n; ++i) {
