p10[0] = 1;
for (int i = 0; i + 1 < P; ++i)
    p10[i + 1] = (p10[i] * 10) % k;

for (int i = 0; i <= k; ++i) {
    d[i] = int(1e9);
    p[i] = -1;
    used[i] = false;
}

d[k] = 0;
while (true) {
    int v = -1;
    for (int i = 0; i <= k; ++i)
        if (!used[i] && (v == -1 || d[v] > d[i]))
            v = i;
    if (v == -1)
        break;   
    if (v == 0)
        break;
    used[v] = true;
    for (int r = 0; r < k; ++r)
        for (int l = 0; l < P; ++l)
            if (any[r][l] != -1) {
                int to = (v * p10[l] + r) % k;
                if (d[to] > d[v] + l) {
                    d[to] = d[v] + l;
                    p[to] = v;
                    w[to] = any[r][l];
                    used[to] = false;
                }
            }               
}   

